using System.ComponentModel.Composition;
using XrmToolBox.Extensibility;
using XrmToolBox.Extensibility.Interfaces;

namespace DiagnosticsWorkbench
{
    /// <summary>
    /// XrmToolBox entry point (discovered through MEF).
    /// Icons: Resources/icon32.png (SmallImageBase64) and Resources/icon80.png (BigImageBase64).
    /// </summary>
    [Export(typeof(IXrmToolBoxPlugin)),
     ExportMetadata("Name", "Dataverse Developer Diagnostics Workbench"),
     ExportMetadata("Description", "Turns plug-in trace logs into diagnostics: groups recurring errors by fingerprint, highlights slow executions, rebuilds correlation chains, flags step configuration issues (filtering attributes, images, recursion) and exports CSV or HTML reports."),
     ExportMetadata("SmallImageBase64", ""),
     ExportMetadata("BigImageBase64", ""),
     ExportMetadata("BackgroundColor", "#E8EAF6"),
     ExportMetadata("PrimaryFontColor", "#303F9F"),
     ExportMetadata("SecondaryFontColor", "#5E6B69")]
    public class DiagnosticsWorkbenchPlugin : PluginBase
    {
        public override IXrmToolBoxPluginControl GetControl()
        {
            return new DiagnosticsWorkbenchControl();
        }
    }
}
